---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Step loader: Named steps with a progress track and four loaders.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change step-loader.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './step-loader.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'wide', 'bare', className]} data-c="step-loader" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="stl dm mx-ic"><div class="dm-main">
  <button class="stl-row mx-press" aria-expanded="false">
    <span class="stl-g"></span>
    <span class="stl-t"><span class="stl-lab shim">Reading Figma frames</span></span>
    <span class="stl-n num">1/4</span>
    <svg class="i xs stl-chev"><use href="#i-chev-d"/></svg>
  </button>
  <div class="stl-track"><i></i><i></i><i></i><i></i></div>
  <div class="fold shut stl-fold"><div><ol class="stl-list mx-rows"></ol></div></div>
  </div>
  <div class="demo"><div class="seg2" role="group" aria-label="Loader"><button aria-pressed="true" data-v="radar">Radar</button><button aria-pressed="false" data-v="think">Dots</button><button aria-pressed="false" data-v="spin">Ring</button><button aria-pressed="false" data-v="bars">Bars</button></div></div>
</div>
  </Fragment></div>
</div>
<script>
  import './step-loader.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Step loader ---------- */
/* a pill with the step in hand (its loader, its name shimmering while it runs, how far along), a track of one part a step
   under it, and a fold that lists every step. The list's marks sit centred under the pill's loader and its words start
   where the pill's do. The pill is a disclosure: pointing at it gives it a quiet fill, never a bigger shadow */
.stl .dm-main{gap:10px}
.stl-row{display:flex;align-items:center;gap:10px;background:var(--dm-surface);border-radius:var(--dm-r-pill);box-shadow:var(--dm-shadow);height:40px;padding:0 14px 0 13px;font-size:13.5px;min-width:250px;transition:background-color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.stl-row:hover{background:color-mix(in srgb,var(--dm-fg) 4%,var(--dm-surface))}}
/* its motion (the core's motion pieces, owner, 26 Nov): a press on the pill shows at once (.mx-press); a mark that changes, the
   loader, the tick or a row's dot, crossfades in place (.mx-ic, iconSwap()); the list's rows settle one after another as it
   opens (.mx-rows) */
.stl-g{width:16px;display:grid;place-items:center;color:var(--dm-fg)}
/* a finished step's tick is the vivid mark green */
.stl-ok{display:grid;color:var(--dm-ok-mark)}
.stl-t{flex:1;text-align:left}
.stl-n{color:var(--dm-muted);font-size:12.5px}
.stl-chev{color:var(--dm-muted);transition:transform .4s var(--dm-ease)}
.stl-row[aria-expanded="true"] .stl-chev{transform:rotate(180deg)}
.stl-track{display:flex;gap:var(--dm-s-1);width:250px}
.stl-track i{flex:1;height:3px;border-radius:var(--dm-r-tiny,2px);background:var(--dm-line);position:relative;overflow:hidden}
.stl-track i::after{content:"";position:absolute;inset:0;background:var(--dm-accent-mark,var(--dm-accent));transform:scaleX(0);transform-origin:left;transition:transform .9s var(--dm-ease)}
.stl-track i.on::after{transform:scaleX(1)}
.stl-track i.run::after{transform:scaleX(.45);transition-duration:2.2s}
.stl-fold{width:250px}
.stl-fold>div{margin-inline:-16px;padding-inline:var(--dm-s-4)}
/* (10px above and below: with a step's own 6px, the first and last steps' words are 16px from the card's edges) */
.stl-list{list-style:none;margin:6px 0 18px;padding:10px 6px;background:var(--dm-surface);border-radius:calc(14px * var(--dm-rk-l,var(--dm-rk)));box-shadow:var(--dm-shadow)}
/* each step's mark centred under the pill's loader (21px in), its words where the pill's start (39px in) */
.stl-list li{display:flex;align-items:center;gap:10px;padding:6px var(--dm-s-2) 6px 7px;font-size:13px;color:var(--dm-muted)}
.stl-list li.done{color:var(--dm-fg2)}.stl-list li.run{color:var(--dm-fg)}
.stl-list li .g{width:16px;display:grid;place-items:center;flex:none}
/* Clean (owner, 19 Nov): the pill is Status pill's Clean pill (36px, a hairline and a short shadow, 13px words) with its
   content 16px in; the list is a round card whose steps sit 8px in from its edges with their words 16px in, so its marks and
   words share the pill's columns (24px and 40px in). The track is the neutral rail with the accent filling it, the tick the
   vivid green, and the motion Clean's calm one */
/* the loader in the pill is the accent, which is white in Clean's dark mode (owner, 21 Nov: "accent color in light mode for
   clean") */
:root[data-style="clean"] .stl-g,:root [data-style="clean"] .stl-g,:root [data-style="clean"].stl-g{color:var(--dm-accent-mark)}
:root[data-style="clean"] .stl-row,:root [data-style="clean"] .stl-row,:root [data-style="clean"].stl-row{height:36px;gap:8px;padding:0 16px;font-size:13px}
:root[data-style="clean"] .stl-chev,:root [data-style="clean"] .stl-chev,:root [data-style="clean"].stl-chev{transition:transform var(--dm-t) var(--dm-ease)}
:root[data-style="clean"] .stl-track i,:root [data-style="clean"] .stl-track i,:root [data-style="clean"].stl-track i{background:var(--dm-rail)}
:root[data-style="clean"] .stl-list,:root [data-style="clean"] .stl-list,:root [data-style="clean"].stl-list{margin:8px 0 16px;padding:8px;border-radius:var(--dm-r-card)}
:root[data-style="clean"] .stl-list li,:root [data-style="clean"] .stl-list li,:root [data-style="clean"].stl-list li{gap:8px;padding:8px;line-height:20px}
/* the row's hover is Clean's one hover laid over its fill (owner, 21 Nov), easing in and out over 220ms */
:root[data-style="clean"] .stl-row,:root [data-style="clean"] .stl-row,:root [data-style="clean"].stl-row{transition:box-shadow var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .stl-row:hover,:root [data-style="clean"] .stl-row:hover,:root [data-style="clean"].stl-row:hover{background:var(--dm-surface);box-shadow:var(--dm-shadow),inset 0 0 0 99px var(--dm-row)}}
/* (its press, the motion pieces' .mx-press: a step deeper than the hover, at once, in the hover's own layer) */
:root[data-style="clean"] .stl-row.mx-press:active,:root [data-style="clean"] .stl-row.mx-press:active,:root [data-style="clean"].stl-row.mx-press:active{box-shadow:var(--dm-shadow),inset 0 0 0 99px var(--dm-row-press);transition-duration:var(--dm-t-press)}
.bars3{display:inline-flex;gap:2px;align-items:center;height:12px}
.bars3 i{width:2.5px;height:100%;border-radius:var(--dm-r-tiny,2px);background:currentColor;animation:b3 .9s var(--dm-ease-io) infinite}
.bars3 i:nth-child(2){animation-delay:.15s}.bars3 i:nth-child(3){animation-delay:.3s}
@keyframes b3{0%,100%{transform:scaleY(.35)}50%{transform:scaleY(1)}}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, iconSwap, seg, swap } from '../core/core.js';
DM.def('step-loader', (r, c) => {
  // the chevron comes from I(), so it points at the icons wherever the component is mounted (designme.dev's own icon ids)
  r.innerHTML = r.innerHTML.replace('{chev}', I('chev-d', 'xs stl-chev'));
  const steps = [['Reading Figma frames','Read 4 frames'],['Matching tokens','Matched 18 tokens'],['Writing components','Wrote 3 components'],['Checking contrast','Contrast passes']];
  const row = $('.stl-row', r), lab = $('.stl-lab', r), n = $('.stl-n', r), g = $('.stl-g', r), bars = $$('.stl-track i', r), list = $('.stl-list', r), fold = $('.stl-fold', r);
  let kind = 'radar', cur = 0, done = false;
  const glyph = () => kind === 'radar' ? '<span class="radar"></span>' : kind === 'think' ? '<span class="think on"><i></i><i></i><i></i><i></i></span>' : kind === 'spin' ? '<span class="spin"></span>' : '<span class="bars3"><i></i><i></i><i></i></span>';
  // the rows stay and change in place: a mark that changes (the loader, the tick, the dot) crossfades (iconSwap()), and one
  // that stays keeps playing where it is
  const MARK = { ok:() => `<span class="stl-ok">${I('ok')}</span>`, check:() => `<span class="stl-ok">${I('check','xs')}</span>`, dot:() => '<span class="dot" style="color:var(--dm-faint)"></span>' };
  const mark = (el, k) => { if (el.dataset.k === k) return; const first = !el.dataset.k; el.dataset.k = k; const put = () => { el.innerHTML = (MARK[k] || glyph)(); }; first ? put() : iconSwap(el, put); };
  list.innerHTML = steps.map(() => '<li><span class="g"></span> </li>').join('');
  const paint = () => {
    mark(g, done ? 'ok' : kind);
    [...list.children].forEach((li, i) => { const fin = i < cur || done;
      li.className = fin ? 'done' : i === cur ? 'run' : ''; mark(li.firstElementChild, fin ? 'check' : i === cur ? kind : 'dot'); li.lastChild.nodeValue = fin ? steps[i][1] : steps[i][0]; });
  };
  seg($('.seg2', r), v => { kind = v; paint(); });
  // the list's rows settle one after another as it opens (.mx-rows)
  row.onclick = () => { const o = fold.classList.toggle('shut'); row.setAttribute('aria-expanded', !o); list.classList.toggle('mx-play', !o); };
  paint();
  c.run(async () => {
    for (;;){
      for (cur = 0; cur < steps.length; cur++){
        bars[cur].classList.add('run'); paint();
        swap(lab, steps[cur][0]); swap(n, (cur + 1) + '/4');
        await c.wait(1900);
        bars[cur].classList.remove('run'); bars[cur].classList.add('on');
      }
      done = true; lab.classList.remove('shim'); swap(lab, 'Ready for review'); swap(n, '4/4'); paint();
      /* hold the finished state, then run the steps again */
      await c.wait(3200);
      // the pill says what runs again as the track empties, never "Ready for review" over an empty track
      done = false; cur = 0; bars.forEach(b => b.classList.remove('on', 'run')); lab.classList.add('shim'); swap(lab, steps[0][0]); swap(n, '1/4'); paint();
      await c.wait(700);
    }
  });
});
